window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e4e7460368d1b60a"]={"versions": [{"id": "FIG-e4e7460368d1b60a", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (AUTOSAR Meta-Modell / MSR-Strukturmodell aus der Spezifikation <code>AUTOSAR_TPS_DiagnosticExtractTemplate</code>, R22-11).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Formales DEXT-Meta-Modell zur Definition der Schnittstelle zwischen der J1939-Diagnosewelt und der AUTOSAR-Systemkommunikation. Es modelliert das Mapping einer SAE J1939 Suspect Parameter Number (<code>DiagnosticJ1939Spn</code>) auf ein Signal des AUTOSAR System-Templates (<code>SystemSignal</code>), optional qualifiziert durch spezifische Quell-Steuergeräte (<code>DiagnosticJ1939Node</code>).\n</li><li><strong>Architektur-Kontext:</strong> Dient Generatoren und BSW-Modulen (insb. <code>J1939Dcm</code>, <code>J1939Rm</code>, <code>Com</code>, <code>Dem</code>) als Zuordnungsbasis, um PGN/SPN-Datenströme des CAN-Netzwerks in interne RTE-/Com-Signale bzw. Dem-Freeze-Frames zu transformieren (Abdeckung von RS_DEXT_00064, TPS_DEXT_01103, TPS_DEXT_01106).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticJ1939SpnMapping</code></strong> <em>(Zentrale Mapping-Klasse)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>DiagnosticMapping</code> (Meta-Klasse aller Diagnose-Mappings).\n</li><li><strong>Funktion:</strong> Verknüpft Diagnose-SPN, SystemSignal und relevante Sender-Knoten.\n</li></ul>\n</li><li><strong><code>DiagnosticJ1939Spn</code></strong> <em>(Diagnose-Entität)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>DiagnosticCommonElement</code>.\n</li><li><strong>Attribute:</strong> <code>+ spn: PositiveInteger [0..1]</code> – Die numerische J1939-Identifikation (gemäß SAE J1939-71).\n</li></ul>\n</li><li><strong><code>SystemSignal</code></strong> <em>(System-Template-Entität)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>ARElement</code>.\n</li><li><strong>Attribute:</strong> <code>+ dynamicLength: Boolean</code> – Flag für Nutzdaten variabler Länge (z. B. ASCII-Strings, proprietäre variabler Payload).\n</li></ul>\n</li><li><strong><code>DiagnosticJ1939Node</code></strong> <em>(Topologie-Entität)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>DiagnosticCommonElement</code>.\n</li><li><strong>Funktion:</strong> Repräsentiert ein logisches J1939-ECU / Controller Application (CA) mit spezifischer Preferred/Source Address.\n</li></ul>\n</li><li><strong>Assoziationen &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticJ1939SpnMapping</code> → <code>DiagnosticJ1939Spn</code> (<code>+spn</code>, Multiplizität: <code>0..1</code>): Unidirektionale Zielreferenz auf die gemappte SPN.\n</li><li><code>DiagnosticJ1939SpnMapping</code> → <code>SystemSignal</code> (<code>+systemSignal</code>, Multiplizität: <code>0..1</code>): Unidirektionale Zielreferenz auf das korrespondierende Signal im Kommunikationsstack.\n</li><li><code>DiagnosticJ1939SpnMapping</code> → <code>DiagnosticJ1939Node</code> (<code>+sendingNode</code>, Multiplizität: <code>0..*</code>): Unidirektionale Referenz auf 0 bis n Ursprungsknoten zur Adressfilterung.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, leitet sich hieraus das Laufzeitverhalten im AUTOSAR Classic Com/Diag-Stack ab:</p>\n<ol class=\"fig-list\"><li><strong>Frame-Empfang &amp; PGN-Extraktion:</strong> <code>CanIf</code> → <code>J1939Tp</code> / <code>PduR</code> → <code>J1939Dcm</code> bzw. <code>Com</code>.\n</li><li><strong>Sender-Validierung:</strong> Bei konfiguriertem <code>sendingNode</code> (<code>1..*</code>) prüft der Stack die Source Address (SA) des J1939-Headers. Stimmt die SA mit keinem der referenzierten <code>DiagnosticJ1939Node</code>s überein, wird das Mapping für diesen Frame verworfen.\n</li><li><strong>Payload-Verarbeitung:</strong>\n<ul class=\"fig-list\"><li>Ist <code>dynamicLength == FALSE</code>: Feste Signal-Länge und Bit-Positionierung (Signalextraktion via Standard-PDU-Unpacking).\n</li><li>Ist <code>dynamicLength == TRUE</code>: Dynamische Längenbestimmung über Transportprotokoll (BAM / CMDT) bzw. PDU-Länge; Signalisierung über dynamische PDU-/Signal-APIs (<code>Com_ReceiveDynSignal</code>).\n</li></ul>\n</li><li><strong>Signal-Routing:</strong> Übergabe an die RTE / Application-SWC oder interne Übergabe an das <code>Dem</code> für DM-Nachrichten (z. B. DM1/DM2-Fehlercode-Kontexte, DM4 Freeze Frames).\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (<code>J1939Dcm</code> &amp; <code>Com</code>):</strong>\n<ul class=\"fig-list\"><li>Tool-Ketten leiten aus <code>DiagnosticJ1939SpnMapping</code> die BSW-Container <code>J1939DcmSpn</code> und deren Zuordnung zu <code>ComSignal</code> ab.\n</li><li>Fehlt die Referenz <code>+systemSignal</code> (<code>0</code>), existiert kein Signalpfad zum <code>Com</code>-Modul; die SPN ist rein diagnoseseitig (z. B. via SWC-Port an den <code>J1939Dcm</code>) zu bedienen.\n</li></ul>\n</li><li><strong>Node-Filtering (<code>sendingNode</code>):</strong>\n<ul class=\"fig-list\"><li>Bei Multiplizität <code>0</code> (kein Knoten referenziert) gilt das Mapping global für alle empfangenen PDUs mit dieser SPN unabhängig vom Sender.\n</li><li>Bei Multiplizität <code>&gt; 0</code> muss der Stack knotenspezifische PGN-Filterung unterstützen, um Fehlzuordnungen identischer SPNs von unterschiedlichen ECUs im selben Busnetzwerk zu verhindern.\n</li></ul>\n</li><li><strong>Signal-Kompatibilität (TPS_DEXT_01103 / TPS_DEXT_01106):</strong>\n<ul class=\"fig-list\"><li>Bitlänge und Datentyp des referenzierten <code>SystemSignal</code> müssen exakt mit der Spezifikation der SAE J1939-71 SPN übereinstimmen.\n</li><li>Wenn <code>dynamicLength == TRUE</code>, muss der BSW-Com-Stack für dynamische Signale konfiguriert sein (<code>ComSignalLengthType</code> dynamisch, Allokation variabler Puffergrößen).\n</li></ul>\n</li></ul>"}, {"id": "FIG-33472a630ac8da08", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (AUTOSAR Meta-Modell / MSR-Strukturmodell aus der Spezifikation <code>AUTOSAR_TPS_DiagnosticExtractTemplate</code>, R22-11).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Formales DEXT-Meta-Modell zur Definition der Schnittstelle zwischen der J1939-Diagnosewelt und der AUTOSAR-Systemkommunikation. Es modelliert das Mapping einer SAE J1939 Suspect Parameter Number (<code>DiagnosticJ1939Spn</code>) auf ein Signal des AUTOSAR System-Templates (<code>SystemSignal</code>), optional qualifiziert durch spezifische Quell-Steuergeräte (<code>DiagnosticJ1939Node</code>).\n</li><li><strong>Architektur-Kontext:</strong> Dient Generatoren und BSW-Modulen (insb. <code>J1939Dcm</code>, <code>J1939Rm</code>, <code>Com</code>, <code>Dem</code>) als Zuordnungsbasis, um PGN/SPN-Datenströme des CAN-Netzwerks in interne RTE-/Com-Signale bzw. Dem-Freeze-Frames zu transformieren (Abdeckung von RS_DEXT_00064, TPS_DEXT_01103, TPS_DEXT_01106).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticJ1939SpnMapping</code></strong> <em>(Zentrale Mapping-Klasse)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>DiagnosticMapping</code> (Meta-Klasse aller Diagnose-Mappings).\n</li><li><strong>Funktion:</strong> Verknüpft Diagnose-SPN, SystemSignal und relevante Sender-Knoten.\n</li></ul>\n</li><li><strong><code>DiagnosticJ1939Spn</code></strong> <em>(Diagnose-Entität)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>DiagnosticCommonElement</code>.\n</li><li><strong>Attribute:</strong> <code>+ spn: PositiveInteger [0..1]</code> – Die numerische J1939-Identifikation (gemäß SAE J1939-71).\n</li></ul>\n</li><li><strong><code>SystemSignal</code></strong> <em>(System-Template-Entität)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>ARElement</code>.\n</li><li><strong>Attribute:</strong> <code>+ dynamicLength: Boolean [0..1]</code> – Flag für Nutzdaten variabler Länge (z. B. ASCII-Strings, proprietäre variable Payload).\n</li></ul>\n</li><li><strong><code>DiagnosticJ1939Node</code></strong> <em>(Topologie-Entität)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>DiagnosticCommonElement</code>.\n</li><li><strong>Funktion:</strong> Repräsentiert ein logisches J1939-ECU / Controller Application (CA) mit spezifischer Preferred/Source Address.\n</li></ul>\n</li><li><strong>Assoziationen &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticJ1939SpnMapping</code> → <code>DiagnosticJ1939Spn</code> (<code>+spn</code>, Multiplizität: <code>0..1</code>): Unidirektionale Zielreferenz auf die gemappte SPN.\n</li><li><code>DiagnosticJ1939SpnMapping</code> → <code>SystemSignal</code> (<code>+systemSignal</code>, Multiplizität: <code>0..1</code>): Unidirektionale Zielreferenz auf das korrespondierende Signal im Kommunikationsstack.\n</li><li><code>DiagnosticJ1939SpnMapping</code> → <code>DiagnosticJ1939Node</code> (<code>+sendingNode</code>, Multiplizität: <code>0..*</code>): Unidirektionale Referenz auf 0 bis n Ursprungsknoten zur Adressfilterung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, leitet sich hieraus das Laufzeitverhalten im AUTOSAR Classic Com/Diag-Stack ab:</p>\n<ol class=\"fig-list\"><li><strong>Frame-Empfang &amp; PGN-Extraktion:</strong> <code>CanIf</code> → <code>J1939Tp</code> / <code>PduR</code> → <code>J1939Dcm</code> bzw. <code>Com</code>.\n</li><li><strong>Sender-Validierung:</strong> Bei konfiguriertem <code>sendingNode</code> (<code>1..*</code>) prüft der Stack die Source Address (SA) des J1939-Headers. Stimmt die SA mit keinem der referenzierten <code>DiagnosticJ1939Node</code>s überein, wird das Mapping für diesen Frame verworfen.\n</li><li><strong>Payload-Verarbeitung:</strong>\n<ul class=\"fig-list\"><li>Ist <code>dynamicLength == FALSE</code>: Feste Signal-Länge und Bit-Positionierung (Signalextraktion via Standard-PDU-Unpacking).\n</li><li>Ist <code>dynamicLength == TRUE</code>: Dynamische Längenbestimmung über Transportprotokoll (BAM / CMDT) bzw. PDU-Länge; Signalisierung über dynamische PDU-/Signal-APIs (<code>Com_ReceiveDynSignal</code>).\n</li></ul>\n</li><li><strong>Signal-Routing:</strong> Übergabe an die RTE / Application-SWC oder interne Übergabe an das <code>Dem</code> für DM-Nachrichten (z. B. DM1/DM2-Fehlercode-Kontexte, DM4 Freeze Frames).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (<code>J1939Dcm</code> &amp; <code>Com</code>):</strong>\n<ul class=\"fig-list\"><li>Tool-Ketten leiten aus <code>DiagnosticJ1939SpnMapping</code> die BSW-Container <code>J1939DcmSpn</code> und deren Zuordnung zu <code>ComSignal</code> ab.\n</li><li>Fehlt die Referenz <code>+systemSignal</code> (<code>0</code>), existiert kein Signalpfad zum <code>Com</code>-Modul; die SPN ist rein diagnoseseitig (z. B. via SWC-Port an den <code>J1939Dcm</code>) zu bedienen.\n</li></ul>\n</li><li><strong>Node-Filtering (<code>sendingNode</code>):</strong>\n<ul class=\"fig-list\"><li>Bei Multiplizität <code>0</code> (kein Knoten referenziert) gilt das Mapping global für alle empfangenen PDUs mit dieser SPN unabhängig vom Sender.\n</li><li>Bei Multiplizität <code>&gt; 0</code> muss der Stack knotenspezifische PGN-Filterung unterstützen, um Fehlzuordnungen identischer SPNs von unterschiedlichen ECUs im selben Busnetzwerk zu verhindern.\n</li></ul>\n</li><li><strong>Signal-Kompatibilität (TPS_DEXT_01103 / TPS_DEXT_01106):</strong>\n<ul class=\"fig-list\"><li>Bitlänge und Datentyp des referenzierten <code>SystemSignal</code> müssen exakt mit der Spezifikation der SAE J1939-71 SPN übereinstimmen.\n</li><li>Wenn <code>dynamicLength == TRUE</code>, muss der BSW-Com-Stack für dynamische Signale konfiguriert sein (<code>ComSignalLengthType</code> dynamisch, Allokation variabler Puffergrößen).\n</li></ul>\n</li></ul>"}, {"id": "FIG-caf24f47f84f802d", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (AUTOSAR Meta-Modell / MSR-Strukturmodell aus der Spezifikation <code>AUTOSAR_TPS_DiagnosticExtractTemplate</code>, R22-11).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Formales DEXT-Meta-Modell zur Definition der Schnittstelle zwischen der J1939-Diagnosewelt und der AUTOSAR-Systemkommunikation. Es modelliert das Mapping einer SAE J1939 Suspect Parameter Number (<code>DiagnosticJ1939Spn</code>) auf ein Signal des AUTOSAR System-Templates (<code>SystemSignal</code>), optional qualifiziert durch spezifische Quell-Steuergeräte (<code>DiagnosticJ1939Node</code>).\n</li><li><strong>Architektur-Kontext:</strong> Dient Generatoren und BSW-Modulen (insb. <code>J1939Dcm</code>, <code>J1939Rm</code>, <code>Com</code>, <code>Dem</code>) als Zuordnungsbasis, um PGN/SPN-Datenströme des CAN-Netzwerks in interne RTE-/Com-Signale bzw. Dem-Freeze-Frames zu transformieren (Abdeckung von RS_DEXT_00064, TPS_DEXT_01103, TPS_DEXT_01106).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticJ1939SpnMapping</code></strong> <em>(Zentrale Mapping-Klasse)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>DiagnosticMapping</code> (Meta-Klasse aller Diagnose-Mappings).\n</li><li><strong>Funktion:</strong> Verknüpft Diagnose-SPN, SystemSignal und relevante Sender-Knoten.\n</li></ul>\n</li><li><strong><code>DiagnosticJ1939Spn</code></strong> <em>(Diagnose-Entität)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>DiagnosticCommonElement</code>.\n</li><li><strong>Attribute:</strong> <code>+ spn: PositiveInteger [0..1]</code> – Die numerische J1939-Identifikation (gemäß SAE J1939-71).\n</li></ul>\n</li><li><strong><code>SystemSignal</code></strong> <em>(System-Template-Entität)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>ARElement</code>.\n</li><li><strong>Attribute:</strong> <code>+ dynamicLength: Boolean [0..1]</code> – Flag für Nutzdaten variabler Länge (z. B. ASCII-Strings, proprietäre variable Payload).\n</li></ul>\n</li><li><strong><code>DiagnosticJ1939Node</code></strong> <em>(Topologie-Entität)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>DiagnosticCommonElement</code>.\n</li><li><strong>Funktion:</strong> Repräsentiert ein logisches J1939-ECU / Controller Application (CA) mit spezifischer Preferred/Source Address.\n</li></ul>\n</li><li><strong>Assoziationen &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticJ1939SpnMapping</code> → <code>DiagnosticJ1939Spn</code> (<code>+spn</code>, Multiplizität: <code>0..1</code>): Unidirektionale Zielreferenz auf die gemappte SPN.\n</li><li><code>DiagnosticJ1939SpnMapping</code> → <code>SystemSignal</code> (<code>+systemSignal</code>, Multiplizität: <code>0..1</code>): Unidirektionale Zielreferenz auf das korrespondierende Signal im Kommunikationsstack.\n</li><li><code>DiagnosticJ1939SpnMapping</code> → <code>DiagnosticJ1939Node</code> (<code>+sendingNode</code>, Multiplizität: <code>0..*</code>): Unidirektionale Referenz auf 0 bis n Ursprungsknoten zur Adressfilterung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, leitet sich hieraus das Laufzeitverhalten im AUTOSAR Classic Com/Diag-Stack ab:</p>\n<ol class=\"fig-list\"><li><strong>Frame-Empfang &amp; PGN-Extraktion:</strong> <code>CanIf</code> → <code>J1939Tp</code> / <code>PduR</code> → <code>J1939Dcm</code> bzw. <code>Com</code>.\n</li><li><strong>Sender-Validierung:</strong> Bei konfiguriertem <code>sendingNode</code> (<code>1..*</code>) prüft der Stack die Source Address (SA) des J1939-Headers. Stimmt die SA mit keinem der referenzierten <code>DiagnosticJ1939Node</code>s überein, wird das Mapping für diesen Frame verworfen.\n</li><li><strong>Payload-Verarbeitung:</strong>\n<ul class=\"fig-list\"><li>Ist <code>dynamicLength == FALSE</code>: Feste Signal-Länge und Bit-Positionierung (Signalextraktion via Standard-PDU-Unpacking).\n</li><li>Ist <code>dynamicLength == TRUE</code>: Dynamische Längenbestimmung über Transportprotokoll (BAM / CMDT) bzw. PDU-Länge; Signalisierung über dynamische PDU-/Signal-APIs (<code>Com_ReceiveDynSignal</code>).\n</li></ul>\n</li><li><strong>Signal-Routing:</strong> Übergabe an die RTE / Application-SWC oder interne Übergabe an das <code>Dem</code> für DM-Nachrichten (z. B. DM1/DM2-Fehlercode-Kontexte, DM4 Freeze Frames).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (<code>J1939Dcm</code> &amp; <code>Com</code>):</strong>\n<ul class=\"fig-list\"><li>Tool-Ketten leiten aus <code>DiagnosticJ1939SpnMapping</code> die BSW-Container <code>J1939DcmSpn</code> und deren Zuordnung zu <code>ComSignal</code> ab.\n</li><li>Fehlt die Referenz <code>+systemSignal</code> (<code>0</code>), existiert kein Signalpfad zum <code>Com</code>-Modul; die SPN ist rein diagnoseseitig (z. B. via SWC-Port an den <code>J1939Dcm</code>) zu bedienen.\n</li></ul>\n</li><li><strong>Node-Filtering (<code>sendingNode</code>):</strong>\n<ul class=\"fig-list\"><li>Bei Multiplizität <code>0</code> (kein Knoten referenziert) gilt das Mapping global für alle empfangenen PDUs mit dieser SPN unabhängig vom Sender.\n</li><li>Bei Multiplizität <code>&gt; 0</code> muss der Stack knotenspezifische PGN-Filterung unterstützen, um Fehlzuordnungen identischer SPNs von unterschiedlichen ECUs im selben Busnetzwerk zu verhindern.\n</li></ul>\n</li><li><strong>Signal-Kompatibilität (TPS_DEXT_01103 / TPS_DEXT_01106):</strong>\n<ul class=\"fig-list\"><li>Bitlänge und Datentyp des referenzierten <code>SystemSignal</code> müssen exakt mit der Spezifikation der SAE J1939-71 SPN übereinstimmen.\n</li><li>Wenn <code>dynamicLength == TRUE</code>, muss der BSW-Com-Stack für dynamische Signale konfiguriert sein (<code>ComSignalLengthType</code> dynamisch, Allokation variabler Puffergrößen).\n</li></ul>\n</li></ul>"}, {"id": "FIG-1ec53bd5dcb946d9", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (AUTOSAR Meta-Modell / MSR-Strukturmodell aus der Spezifikation <code>AUTOSAR_TPS_DiagnosticExtractTemplate</code>, R22-11).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Formales DEXT-Meta-Modell zur Definition der Schnittstelle zwischen der J1939-Diagnosewelt und der AUTOSAR-Systemkommunikation. Es modelliert das Mapping einer SAE J1939 Suspect Parameter Number (<code>DiagnosticJ1939Spn</code>) auf ein Signal des AUTOSAR System-Templates (<code>SystemSignal</code>), optional qualifiziert durch spezifische Quell-Steuergeräte (<code>DiagnosticJ1939Node</code>).\n</li><li><strong>Architektur-Kontext:</strong> Dient Generatoren und BSW-Modulen (insb. <code>J1939Dcm</code>, <code>J1939Rm</code>, <code>Com</code>, <code>Dem</code>) als Zuordnungsbasis, um PGN/SPN-Datenströme des CAN-Netzwerks in interne RTE-/Com-Signale bzw. Dem-Freeze-Frames zu transformieren (Abdeckung von RS_DEXT_00064, TPS_DEXT_01103, TPS_DEXT_01106).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticJ1939SpnMapping</code></strong> <em>(Zentrale Mapping-Klasse)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>DiagnosticMapping</code> (Meta-Klasse aller Diagnose-Mappings).\n</li><li><strong>Funktion:</strong> Verknüpft Diagnose-SPN, SystemSignal und relevante Sender-Knoten.\n</li></ul>\n</li><li><strong><code>DiagnosticJ1939Spn</code></strong> <em>(Diagnose-Entität)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>DiagnosticCommonElement</code>.\n</li><li><strong>Attribute:</strong> <code>+ spn: PositiveInteger [0..1]</code> – Die numerische J1939-Identifikation (gemäß SAE J1939-71).\n</li></ul>\n</li><li><strong><code>SystemSignal</code></strong> <em>(System-Template-Entität)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>ARElement</code>.\n</li><li><strong>Attribute:</strong> <code>+ dynamicLength: Boolean [0..1]</code> – Flag für Nutzdaten variabler Länge (z. B. ASCII-Strings, proprietäre variable Payload).\n</li></ul>\n</li><li><strong><code>DiagnosticJ1939Node</code></strong> <em>(Topologie-Entität)</em>\n<ul class=\"fig-list\"><li><strong>Superklasse:</strong> <code>DiagnosticCommonElement</code>.\n</li><li><strong>Funktion:</strong> Repräsentiert ein logisches J1939-ECU / Controller Application (CA) mit spezifischer Preferred/Source Address.\n</li></ul>\n</li><li><strong>Assoziationen &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticJ1939SpnMapping</code> → <code>DiagnosticJ1939Spn</code> (<code>+spn</code>, Multiplizität: <code>0..1</code>): Unidirektionale Zielreferenz auf die gemappte SPN.\n</li><li><code>DiagnosticJ1939SpnMapping</code> → <code>SystemSignal</code> (<code>+systemSignal</code>, Multiplizität: <code>0..1</code>): Unidirektionale Zielreferenz auf das korrespondierende Signal im Kommunikationsstack.\n</li><li><code>DiagnosticJ1939SpnMapping</code> → <code>DiagnosticJ1939Node</code> (<code>+sendingNode</code>, Multiplizität: <code>0..*</code>): Unidirektionale Referenz auf 0 bis n Ursprungsknoten zur Adressfilterung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, leitet sich hieraus das Laufzeitverhalten im AUTOSAR Classic Com/Diag-Stack ab:</p>\n<ol class=\"fig-list\"><li><strong>Frame-Empfang &amp; PGN-Extraktion:</strong> <code>CanIf</code> → <code>J1939Tp</code> / <code>PduR</code> → <code>J1939Dcm</code> bzw. <code>Com</code>.\n</li><li><strong>Sender-Validierung:</strong> Bei konfiguriertem <code>sendingNode</code> (<code>1..*</code>) prüft der Stack die Source Address (SA) des J1939-Headers. Stimmt die SA mit keinem der referenzierten <code>DiagnosticJ1939Node</code>s überein, wird das Mapping für diesen Frame verworfen.\n</li><li><strong>Payload-Verarbeitung:</strong>\n<ul class=\"fig-list\"><li>Ist <code>dynamicLength == FALSE</code>: Feste Signal-Länge und Bit-Positionierung (Signalextraktion via Standard-PDU-Unpacking).\n</li><li>Ist <code>dynamicLength == TRUE</code>: Dynamische Längenbestimmung über Transportprotokoll (BAM / CMDT) bzw. PDU-Länge; Signalisierung über dynamische PDU-/Signal-APIs (<code>Com_ReceiveDynSignal</code>).\n</li></ul>\n</li><li><strong>Signal-Routing:</strong> Übergabe an die RTE / Application-SWC oder interne Übergabe an das <code>Dem</code> für DM-Nachrichten (z. B. DM1/DM2-Fehlercode-Kontexte, DM4 Freeze Frames).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (<code>J1939Dcm</code> &amp; <code>Com</code>):</strong>\n<ul class=\"fig-list\"><li>Tool-Ketten leiten aus <code>DiagnosticJ1939SpnMapping</code> die BSW-Container <code>J1939DcmSpn</code> und deren Zuordnung zu <code>ComSignal</code> ab.\n</li><li>Fehlt die Referenz <code>+systemSignal</code> (<code>0</code>), existiert kein Signalpfad zum <code>Com</code>-Modul; die SPN ist rein diagnoseseitig (z. B. via SWC-Port an den <code>J1939Dcm</code>) zu bedienen.\n</li></ul>\n</li><li><strong>Node-Filtering (<code>sendingNode</code>):</strong>\n<ul class=\"fig-list\"><li>Bei Multiplizität <code>0</code> (kein Knoten referenziert) gilt das Mapping global für alle empfangenen PDUs mit dieser SPN unabhängig vom Sender.\n</li><li>Bei Multiplizität <code>&gt; 0</code> muss der Stack knotenspezifische PGN-Filterung unterstützen, um Fehlzuordnungen identischer SPNs von unterschiedlichen ECUs im selben Busnetzwerk zu verhindern.\n</li></ul>\n</li><li><strong>Signal-Kompatibilität (TPS_DEXT_01103 / TPS_DEXT_01106):</strong>\n<ul class=\"fig-list\"><li>Bitlänge und Datentyp des referenzierten <code>SystemSignal</code> müssen exakt mit der Spezifikation der SAE J1939-71 SPN übereinstimmen.\n</li><li>Wenn <code>dynamicLength == TRUE</code>, muss der BSW-Com-Stack für dynamische Signale konfiguriert sein (<code>ComSignalLengthType</code> dynamisch, Allokation variabler Puffergrößen).\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-e4e7460368d1b60a", "to": "FIG-33472a630ac8da08", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>SystemSignal</code>: Attribut <code>dynamicLength</code> erhält die Multiplizität <code>[0..1]</code> (<code>+ dynamicLength: Boolean [0..1]</code>).\n</li></ul>"}, {"from": "FIG-33472a630ac8da08", "to": "FIG-caf24f47f84f802d", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-caf24f47f84f802d", "to": "FIG-1ec53bd5dcb946d9", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>DiagnosticJ1939Node</code>: Vertikaler Abstand zu <code>DiagnosticJ1939SpnMapping</code> verringert und Assoziationslinie <code>+sendingNode</code> verkürzt (kompakteres Layout).\n</li></ul>"}]};
